SELECT id, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, CUME_DIST() OVER (PARTITION BY level ORDER BY salary) AS salary_cume_dist, AVG(salary) OVER (PARTITION BY YEAR(hire_date), manager_id ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS salary_avg_3, SUM(salary) OVER (PARTITION BY manager_id, dept_id ORDER BY salary, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_salary, AVG(salary) OVER (PARTITION BY manager_id ORDER BY hire_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS salary_avg_3_2 FROM employees WHERE salary BETWEEN 111000 AND 133000
